#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    const char *in = argv[1];
    size_t len = strlen(in);
    if (len == 0 || len > 31) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (in[i] != '0' && in[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    // copy input to mutable tape
    char tape[32];
    memcpy(tape, in, len);
    tape[len] = '\0';

    int steps = 0;
    // The least‑significant bit is at the leftmost position (index 0).
    // Increment by scanning rightwards for the first '0'.
    size_t pos = 0;
    while (pos < len && tape[pos] == '1') {
        // turn 1 into 0 and move left (simulated by moving right in this representation)
        tape[pos] = '0';
        ++steps; // write step
        ++pos;    // move right
        ++steps; // move step
    }
    if (pos == len) {
        // overflow – all bits were 1
        puts("OVERFLOW");
        printf(" steps=%d\n", steps);
        return 0;
    }
    // we have found a '0' at position pos; turn it into '1'
    tape[pos] = '1';
    ++steps; // write step

    // output result
    printf("result=");
    for (size_t i = 0; i < len; ++i) {
        putchar(tape[i]);
    }
    printf(" steps=%d\n", steps);
    return 0;
}
